static real_T AbstractDetectionGenerator_lookupProfileIndex(const emlrtStack *sp,
  visionDetectionGenerator *obj, real_T actorID)
{
  static const int32_T iv[2] = { 1, 63 };

  static const int32_T iv1[2] = { 1, 63 };

  static char_T b_u[63] = { 'd', 'r', 'i', 'v', 'i', 'n', 'g', ':', 'a', 'b',
    's', 't', 'r', 'a', 'c', 't', 'D', 'e', 't', 'e', 'c', 't', 'i', 'o', 'n',
    'G', 'e', 'n', 'e', 'r', 'a', 't', 'o', 'r', ':', 'm', 'a', 't', 'c', 'h',
    'i', 'n', 'g', 'A', 'c', 't', 'o', 'r', 'P', 'r', 'o', 'f', 'i', 'l', 'e',
    'N', 'o', 't', 'F', 'o', 'u', 'n', 'd' };

  emlrtStack st;
  const mxArray *b_y;
  const mxArray *c_y;
  const mxArray *m;
  const mxArray *y;
  sFvgbgI4AYXVHzrz3A0KzPF s[2];
  real_T ind;
  int32_T idx;
  int32_T ii;
  int32_T ii_size_idx_1;
  char_T u[63];
  int8_T ii_data_idx_0;
  int8_T ind_data_idx_0;
  boolean_T x[2];
  boolean_T exitg1;
  st.prev = sp;
  st.tls = sp->tls;
  if (obj->pActorIDMatchRequired) {
    for (idx = 0; idx < 2; idx++) {
      s[idx] = obj->pActorProfiles[idx];
    }

    for (idx = 0; idx < 2; idx++) {
      x[idx] = (s[idx].ActorID == actorID);
    }

    idx = 0;
    ii_size_idx_1 = 1;
    ii = 1;
    exitg1 = false;
    while ((!exitg1) && (ii - 1 < 2)) {
      if (x[ii - 1]) {
        idx = 1;
        ii_data_idx_0 = (int8_T)ii;
        exitg1 = true;
      } else {
        ii++;
      }
    }

    if (idx == 0) {
      ii_size_idx_1 = 0;
    }

    for (idx = 0; idx < ii_size_idx_1; idx++) {
      ind_data_idx_0 = ii_data_idx_0;
    }

    if (ii_size_idx_1 == 0) {
      for (idx = 0; idx < 63; idx++) {
        u[idx] = b_u[idx];
      }

      y = NULL;
      m = emlrtCreateCharArray(2, &iv[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 63, m, &u[0]);
      emlrtAssign(&y, m);
      for (idx = 0; idx < 63; idx++) {
        u[idx] = b_u[idx];
      }

      b_y = NULL;
      m = emlrtCreateCharArray(2, &iv1[0]);
      emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 63, m, &u[0]);
      emlrtAssign(&b_y, m);
      c_y = NULL;
      m = emlrtCreateDoubleScalar(actorID);
      emlrtAssign(&c_y, m);
      st.site = &cr_emlrtRSI;
      error(&st, y, getString(&st, message(&st, b_y, c_y, &lb_emlrtMCI),
             &lb_emlrtMCI), &lb_emlrtMCI);
    }

    emlrtDynamicBoundsCheckR2012b(1, 1, ii_size_idx_1, &jc_emlrtBCI,
      (emlrtConstCTX)sp);
    ind = (real_T)ind_data_idx_0;
  } else {
    ind = 1.0;
  }

  return ind;
}

