static void b_sort(real_T x_data[], int32_T x_size[1], int32_T idx_data[],
                   int32_T idx_size[1])
{
  real_T vwork_data[106];
  int32_T iidx_data[106];
  int32_T iidx_size[1];
  int32_T vwork_size[1];
  int32_T b_i;
  int32_T dim;
  int32_T i;
  int32_T j;
  int32_T k;
  int32_T vstride;
  dim = 1;
  if (x_size[0] != 1) {
    dim = 0;
    i = x_size[0];
  } else {
    i = 1;
  }

  vwork_size[0] = i;
  idx_size[0] = x_size[0];
  vstride = 1;
  dim--;
  for (k = 0; k <= dim; k++) {
    vstride *= x_size[0];
  }

  for (b_i = 0; b_i < 1; b_i++) {
    for (j = 0; j < vstride; j++) {
      dim = i - 1;
      for (k = 0; k <= dim; k++) {
        vwork_data[k] = x_data[j + k * vstride];
      }

      sortIdx(vwork_data, vwork_size, iidx_data, iidx_size);
      dim = i - 1;
      for (k = 0; k <= dim; k++) {
        x_data[j + k * vstride] = vwork_data[k];
        idx_data[j + k * vstride] = iidx_data[k];
      }
    }
  }
}

static void sortIdx(real_T x_data[], int32_T x_size[1], int32_T idx_data[],
                    int32_T idx_size[1])
{
  real_T b_x_data[106];
  real_T xwork_data[106];
  real_T x4[4];
  int32_T iwork_data[106];
  int32_T perm[4];
  int32_T b_x_size[1];
  int32_T xwork_size[1];
  int32_T b_i;
  int32_T i;
  int32_T i3;
  int32_T i4;
  int32_T ib;
  int32_T k;
  int32_T n;
  int32_T nNaNs;
  int32_T quartetOffset;
  int8_T idx4[4];
  int8_T unnamed_idx_0;
  unnamed_idx_0 = (int8_T)x_size[0];
  idx_size[0] = x_size[0];
  i = x_size[0];
  for (b_i = 0; b_i < i; b_i++) {
    idx_data[b_i] = 0;
  }

  if (x_size[0] != 0) {
    b_x_size[0] = x_size[0];
    i = x_size[0];
    if (i - 1 >= 0) {
      memcpy(&b_x_data[0], &x_data[0], (uint32_T)i * sizeof(real_T));
    }

    idx_size[0] = unnamed_idx_0;
    i = unnamed_idx_0;
    for (b_i = 0; b_i < i; b_i++) {
      idx_data[b_i] = 0;
    }

    n = x_size[0];
    for (i = 0; i < 4; i++) {
      x4[i] = 0.0;
      idx4[i] = 0;
    }

    i = unnamed_idx_0;
    for (b_i = 0; b_i < i; b_i++) {
      iwork_data[b_i] = 0;
    }

    xwork_size[0] = x_size[0];
    i = xwork_size[0];
    for (b_i = 0; b_i < i; b_i++) {
      xwork_data[b_i] = 0.0;
    }

    nNaNs = 0;
    ib = 0;
    b_i = x_size[0] - 1;
    for (k = 0; k <= b_i; k++) {
      if (muDoubleScalarIsNaN(b_x_data[k])) {
        idx_data[(n - nNaNs) - 1] = k + 1;
        xwork_data[(n - nNaNs) - 1] = b_x_data[k];
        nNaNs++;
      } else {
        ib++;
        idx4[ib - 1] = (int8_T)(k + 1);
        x4[ib - 1] = b_x_data[k];
        if (ib == 4) {
          quartetOffset = k - nNaNs;
          if (x4[0] <= x4[1]) {
            i = 1;
            ib = 2;
          } else {
            i = 2;
            ib = 1;
          }

          if (x4[2] <= x4[3]) {
            i3 = 3;
            i4 = 4;
          } else {
            i3 = 4;
            i4 = 3;
          }

          if (x4[i - 1] <= x4[i3 - 1]) {
            if (x4[ib - 1] <= x4[i3 - 1]) {
              perm[0] = i;
              perm[1] = ib;
              perm[2] = i3;
              perm[3] = i4;
            } else if (x4[ib - 1] <= x4[i4 - 1]) {
              perm[0] = i;
              perm[1] = i3;
              perm[2] = ib;
              perm[3] = i4;
            } else {
              perm[0] = i;
              perm[1] = i3;
              perm[2] = i4;
              perm[3] = ib;
            }
          } else if (x4[i - 1] <= x4[i4 - 1]) {
            if (x4[ib - 1] <= x4[i4 - 1]) {
              perm[0] = i3;
              perm[1] = i;
              perm[2] = ib;
              perm[3] = i4;
            } else {
              perm[0] = i3;
              perm[1] = i;
              perm[2] = i4;
              perm[3] = ib;
            }
          } else {
            perm[0] = i3;
            perm[1] = i4;
            perm[2] = i;
            perm[3] = ib;
          }

          idx_data[quartetOffset - 3] = idx4[perm[0] - 1];
          idx_data[quartetOffset - 2] = idx4[perm[1] - 1];
          idx_data[quartetOffset - 1] = idx4[perm[2] - 1];
          idx_data[quartetOffset] = idx4[perm[3] - 1];
          b_x_data[quartetOffset - 3] = x4[perm[0] - 1];
          b_x_data[quartetOffset - 2] = x4[perm[1] - 1];
          b_x_data[quartetOffset - 1] = x4[perm[2] - 1];
          b_x_data[quartetOffset] = x4[perm[3] - 1];
          ib = 0;
        }
      }
    }

    i3 = (x_size[0] - nNaNs) - 1;
    if (ib > 0) {
      for (i = 0; i < 4; i++) {
        perm[i] = 0;
      }

      if (ib == 1) {
        perm[0] = 1;
      } else if (ib == 2) {
        if (x4[0] <= x4[1]) {
          perm[0] = 1;
          perm[1] = 2;
        } else {
          perm[0] = 2;
          perm[1] = 1;
        }
      } else if (x4[0] <= x4[1]) {
        if (x4[1] <= x4[2]) {
          perm[0] = 1;
          perm[1] = 2;
          perm[2] = 3;
        } else if (x4[0] <= x4[2]) {
          perm[0] = 1;
          perm[1] = 3;
          perm[2] = 2;
        } else {
          perm[0] = 3;
          perm[1] = 1;
          perm[2] = 2;
        }
      } else if (x4[0] <= x4[2]) {
        perm[0] = 2;
        perm[1] = 1;
        perm[2] = 3;
      } else if (x4[1] <= x4[2]) {
        perm[0] = 2;
        perm[1] = 3;
        perm[2] = 1;
      } else {
        perm[0] = 3;
        perm[1] = 2;
        perm[2] = 1;
      }

      b_i = (uint8_T)ib - 1;
      for (k = 0; k <= b_i; k++) {
        quartetOffset = perm[k];
        idx_data[((i3 - ib) + k) + 1] = idx4[quartetOffset - 1];
        b_x_data[((i3 - ib) + k) + 1] = x4[quartetOffset - 1];
      }
    }

    i = nNaNs >> 1;
    for (k = 0; k < i; k++) {
      quartetOffset = idx_data[(i3 + k) + 1];
      idx_data[(i3 + k) + 1] = idx_data[(n - k) - 1];
      idx_data[(n - k) - 1] = quartetOffset;
      b_x_data[(i3 + k) + 1] = xwork_data[(n - k) - 1];
      b_x_data[(n - k) - 1] = xwork_data[(i3 + k) + 1];
    }

    if ((nNaNs & 1) != 0) {
      b_x_data[(i3 + i) + 1] = xwork_data[(i3 + i) + 1];
    }

    i = x_size[0] - nNaNs;
    if (i > 1) {
      merge_block(idx_data, b_x_data, i, iwork_data, xwork_data);
    }

    x_size[0] = b_x_size[0];
    if (b_x_size[0] - 1 >= 0) {
      memcpy(&x_data[0], &b_x_data[0], (uint32_T)b_x_size[0] * sizeof(real_T));
    }
  }
}

static void merge_block(int32_T idx_data[], real_T x_data[], int32_T n, int32_T
  iwork_data[], real_T xwork_data[])
{
  int32_T bLen;
  int32_T nPairs;
  int32_T nTail;
  int32_T tailOffset;
  nPairs = n >> 2;
  bLen = 4;
  while (nPairs > 1) {
    if ((nPairs & 1) != 0) {
      nPairs--;
      tailOffset = bLen * nPairs;
      nTail = n - tailOffset;
      if (nTail > bLen) {
        merge(idx_data, x_data, tailOffset, bLen, nTail - bLen, iwork_data,
              xwork_data);
      }
    }

    tailOffset = bLen << 1;
    nPairs >>= 1;
    for (nTail = 0; nTail < nPairs; nTail++) {
      merge(idx_data, x_data, nTail * tailOffset, bLen, bLen, iwork_data,
            xwork_data);
    }

    bLen = tailOffset;
  }

  if (n > bLen) {
    merge(idx_data, x_data, 0, bLen, n - bLen, iwork_data, xwork_data);
  }
}

static void merge(int32_T idx_data[], real_T x_data[], int32_T offset, int32_T
                  np, int32_T nq, int32_T iwork_data[], real_T xwork_data[])
{
  int32_T exitg1;
  int32_T iout;
  int32_T n;
  int32_T p;
  int32_T qend;
  if (nq != 0) {
    n = (np + nq) - 1;
    for (qend = 0; qend <= n; qend++) {
      iwork_data[qend] = idx_data[offset + qend];
      xwork_data[qend] = x_data[offset + qend];
    }

    p = 0;
    n = np;
    qend = np + nq;
    iout = offset - 1;
    do {
      exitg1 = 0;
      iout++;
      if (xwork_data[p] <= xwork_data[n]) {
        idx_data[iout] = iwork_data[p];
        x_data[iout] = xwork_data[p];
        if (p + 1 < np) {
          p++;
        } else {
          exitg1 = 1;
        }
      } else {
        idx_data[iout] = iwork_data[n];
        x_data[iout] = xwork_data[n];
        if (n + 1 < qend) {
          n++;
        } else {
          n = iout - p;
          for (qend = p + 1; qend <= np; qend++) {
            idx_data[n + qend] = iwork_data[qend - 1];
            x_data[n + qend] = xwork_data[qend - 1];
          }

          exitg1 = 1;
        }
      }
    } while (exitg1 == 0);
  }
}

